public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        Map<Integer, List<int[]>> graph = new HashMap<>();
        for (int[] path : paths) {
            graph.computeIfAbsent(path[0], k -> new ArrayList<>()).add(new int[]{path[1], path[2]});
            graph.computeIfAbsent(path[1], k -> new ArrayList<>()).add(new int[]{path[0], path[2]});
        }
        Set<Integer> visited = new HashSet<>();
        boolean[] result = {false};
        dfs(graph, start[0], end[0], visited, result);
        return result[0] ? "can be travelled" : "cannot be travelled";
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[] visited = new boolean[n];
    List<Integer> graph[] = new List[n];

    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }

    for (int[] path : paths) {
        int u = path[0];
        int v = path[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    if (dfs(graph, visited, start[0], end[0])) {
        return "can be travelled";
    } else {
        return "cannot be travelled";
    }
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create an adjacency list to represent the maze
    List<Integer>[] adjacencyList = new List[n * n];
    for (int i = 0; i < adjacencyList.length; i++) {
        adjacencyList[i] = new ArrayList<>();
    }

    // Populate the adjacency list with the given paths
    for (int[] path : paths) {
        int from = path[0];
        int to = path[1];
        adjacencyList[from].add(to);
        adjacencyList[to].add(from);
    }

    // Helper method to perform DFS and check if end can be reached from start
    boolean[] visited = new boolean[n * n];
    if (!dfs(start[0] * n + start[1], end[0] * n + end[1], adjacencyList, visited)) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] grid = new boolean[n][n];
    for (int[] path : paths) {
        int x1 = path[0];
        int y1 = path[1];
        int x2 = path[2];
        int y2 = path[3];
        grid[x1][y1] = true;
        grid[x2][y2] = true;
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new ArrayDeque<>();
    queue.add(start);
    visited[start[0]][start[1]] = true;

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] direction : directions) {
            int x = current[0] + direction[0];
            int y = current[1] + direction[1];

            if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] && !visited[x][y]) {
                queue.add(new int[]{x, y});
                visited[x][y] = true;
            }
        }
    }

    return "cannot be travelled";
}

