        Set<Character> set2 = new HashSet<>();

        // Add characters of word1 to set1
        for (char c : word1.toCharArray()) {
            set1.add(c);
        }

        // Add characters of word2 to set2
        for (char c : word2.toCharArray()) {
            set2.add(c);
        }

        // Find common characters
        set1.retainAll(set2);

        // Number of common characters
        int commonCount = set1.size();

        // Sum of lengths of the two words
        int totalLength = word1.length() + word2.length();

        // Calculate the greatest common divisor (GCD) of commonCount and totalLength
        int gcd = gcd(commonCount, totalLength);

        // Reduce the fraction
