public double trimMean(int[] arr) {
    Arrays.sort(arr);
    int n = arr.length;
    int start = (int) (0.05 * n);
    int end = (int) (0.95 * n);
    int sum = 0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    return (double) sum / (end - start);
}

