public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int sum = 0;
    for (int num : nums) sum += num;
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) return true;
    }
    Set<Integer>[] dp = new Set[n / 2 + 1];
    for (int i = 1; i <= n / 2; i++) {
        dp[i] = new HashSet<>();
    }
    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (int x : dp[i - 1]) {
                dp[i].add(x + num);
            }
        }
        dp[1].add(num);
    }
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i].contains(sum * i / n)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[] possibleSums = new boolean[sum + 1];
    possibleSums[nums[0]] = true;
    possibleSums[0] = true;

    for (int i = 1; i < n; i++) {
        boolean[] newSums = new boolean[sum + 1];
        for (int j = sum; j >= 0; j--) {
            if (possibleSums[j]) {
                newSums[j] = true;
                newSums[j + nums[i]] = true;
            }
        }
        possibleSums = newSums;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (possibleSums[i * sum / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    double totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    for (int i = 0; i < 1 << n; i++) {
        int sum = 0, count = 0;
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) > 0) {
                sum += nums[j];
                count++;
            }
        }
        if (count > 0 && count < n && sum * n == totalSum * count) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    List<Integer>[] dp = new ArrayList[n / 2 + 1];
    for (int i = 0; i < dp.length; i++) {
        dp[i] = new ArrayList<>();
    }

    dp[0].add(0);
    dp[1].add(nums[0]);

    for (int i = 1; i < n; i++) {
        for (int j = Math.min(i, n / 2); j > 0; j--) {
            for (int num : dp[j - 1]) {
                dp[j].add(num + nums[i]);
            }
        }
        dp[1].add(nums[i]);
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int num : dp[i]) {
            if (num * n == sum * i) {
                return true;
            }
        }
    }

    return false;
}

