        if (s.length() < Math.pow(2, k)) {
            return false;
        }
        Set<String> seen = new HashSet<>();
        for (int i = 0; i <= s.length() - k; i++) {
            seen.add(s.substring(i, i + k));
        }
        return seen.size() == Math.pow(2, k);
    }

public boolean hasAllCodes(String s, int k) {
    int totalCombinations = 1 << k; // 2^k
    boolean[] seen = new boolean[totalCombinations];
    int uniqueCount = 0;
    int hash = 0;

    for (int i = 0; i < s.length(); i++) {
        hash = (hash << 1) & (totalCombinations - 1); // Shift left and keep only k bits
        hash |= s.charAt(i) - '0'; // Add the current bit

        if (i >= k - 1) {
            if (!seen[hash]) {
                seen[hash] = true;
                uniqueCount++;
            }
        }
    }

    return uniqueCount == totalCombinations;
}

