public int minInsertions(String s) {
    int left = 0;
    int right = 0;
    int count = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            if (right % 2 == 1) {
                count++;
                right--;
            }
            left++;
        } else {
            right++;
            if (right == 0 && i != s.length() - 1) {
                count++;
            } else if (right > left) {
                count++;
                left++;
            }
        }
    }

    count += Math.abs(left - right) + (right % 2 == 1 ? 1 : 0);
    return count;
}

public int minInsertions(String s) {
        int bal = 0; // Balance of the parentheses
        int insertions = 0; // Number of insertions needed

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                    i++; // Skip the next character as it is a valid pair
                } else {
                    insertions++; // Insert a ')' to balance the current '('
                }
                bal++; // Increase balance for the '('
            } else {
                bal--; // Decrease balance for the ')'

                // If balance is negative, it means there are more ')' than '('
                if (bal == -1) {
                    insertions++; // Insert a '(' to balance the current ')'
                    bal = 0; // Reset balance
                }
            }
        }

        // If balance is positive, it means there are more '(' than ')'
        return insertions + 2 * bal; // Each extra '(' needs a matching ')'
    }

