public int findMinFibonacciNumbers(int k) {
    List<Integer> fibNumbers = new ArrayList<>();
    int a = 1, b = 1;
    while (a <= k) {
        fibNumbers.add(a);
        int temp = a;
        a = b;
        b = temp + b;
    }

    int count = 0;
    for (int i = fibNumbers.size() - 1; i >= 0; i--) {
        if (fibNumbers.get(i) <= k) {
            k -= fibNumbers.get(i);
            count++;
        }
        if (k == 0) {
            break;
        }
    }

    return count;
}

