    while (b + a <= k) {
        int temp = a + b;
        a = b;
        b = temp;
        fibNumbers.add(b);
    }

    int count = 0;
    // Use largest Fibonacci numbers first to minimize the count
    for (int i = fibNumbers.size() - 1; i >= 0; i--) {
        if (fibNumbers.get(i) <= k) {
            count += k / fibNumbers.get(i);
            k %= fibNumbers.get(i);
        }
        if (k == 0) {
            break;
        }
    }

    return count;
}

