    StringBuilder stack = new StringBuilder();

    for (char c : s.toCharArray()) {
        if (stack.length() == 0) {
            stack.append(c);
        } else {
            if (Character.isLowerCase(c) && Character.toUpperCase(c) == stack.charAt(stack.length() - 1)) {
                stack.deleteCharAt(stack.length() - 1);
            } else if (Character.isUpperCase(c) && Character.toLowerCase(c) == stack.charAt(stack.length() - 1)) {
                stack.deleteCharAt(stack.length() - 1);
            } else {
                stack.append(c);
            }
        }
    }

    return stack.toString();
}

