public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) return result;

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            if (i >= low && i <= high) {
                result.add(i);
            }
            if (i == 0) continue;
            queue.offer(i);
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            int lastDigit = num % 10;

            if (lastDigit > 0) {
                int nextNum = num * 10 + (lastDigit - 1);
                if (nextNum <= high) {
                    if (nextNum >= low) {
                        result.add(nextNum);
                    }
                    queue.offer(nextNum);
                }
            }
            if (lastDigit < 9) {
                int nextNum = num * 10 + (lastDigit + 1);
                if (nextNum <= high) {
                    if (nextNum >= low) {
                        result.add(nextNum);
                    }
                    queue.offer(nextNum);
                }
            }
        }

        result.sort(Integer::compareTo);
        return result;
    }

