public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    int[][][] dp = new int[m + 1][n + 1][4]; // 0: vertical, 1: horizontal, 2: diagonal, 3: anti-diagonal

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            if (mat[i - 1][j - 1] == 1) {
                dp[i][j][0] = dp[i - 1][j][0] + 1; // vertical
                dp[i][j][1] = dp[i][j - 1][1] + 1; // horizontal
                dp[i][j][2] = dp[i - 1][j - 1][2] + 1; // diagonal
                dp[i][j][3] = dp[i - 1][j + 1][3] + 1; // anti-diagonal

                maxLength = Math.max(maxLength, dp[i][j][0]);
                maxLength = Math.max(maxLength, dp[i][j][1]);
                maxLength = Math.max(maxLength, dp[i][j][2]);
                maxLength = Math.max(maxLength, dp[i][j][3]);
            }
        }
    }

    return maxLength;
}

public static int longestLine(int[][] mat) {
        int n = mat.length;
        if (n == 0) return 0;
        int m = mat[0].length;
        if (m == 0) return 0;

        int[][][] dp = new int[n][m][4]; // 4 states: horizontal, vertical, diagonal, anti-diagonal

        int ans = 0;

        for (int[] row : dp) {
            for (int[] col : row) {
                Arrays.fill(col, 0);
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (mat[i][j] == 1) {
                    // Horizontal
                    dp[i][j][0] = (j > 0 ? dp[i][j - 1][0] : 0) + 1;
                    // Vertical
                    dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;
                    // Diagonal
                    dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1;
                    // Anti-diagonal
                    dp[i][j][3] = (i > 0 && j < m - 1 ? dp[i - 1][j + 1][3] : 0) + 1;
                    ans = Math.max(ans, Math.max(dp[i][j][0], Math.max(dp[i][j][1], Math.max(dp[i][j][2], dp[i][j][3]))));
                }
            }
        }

        return ans;
    }

