public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int k = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            // Top-bottom diagonal
            int r = Math.min(d, rows - 1);
            int c = d - r;
            while (r >= 0 && c < cols) {
                result[k++] = mat[r--][c++];
            }
        } else {
            // Bottom-top diagonal
            int c = Math.min(d, cols - 1);
            int r = d - c;
            while (c >= 0 && r < rows) {
                result[k++] = mat[r++][c--];
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
