    int[] result = new int[rows * cols];
    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            for (int i = Math.min(d, rows - 1); i >= Math.max(0, d - cols + 1); i--) {
                result[index++] = mat[i][d - i];
            }
        } else {
            for (int i = Math.max(0, d - cols + 1); i <= Math.min(d, rows - 1); i++) {
                result[index++] = mat[i][d - i];
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0) return new int[0];

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, index = 0;

    while (r < rows && c < cols) {
        result[index++] = mat[r][c];
        if ((r + c) % 2 == 0) {
            if (c == cols - 1) r++;
            else if (r == 0) c++;
            else {
                r--;
                c++;
            }
        } else {
            if (r == rows - 1) c++;
            else if (c == 0) r++;
            else {
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;

    // Find the first digit that is smaller than the digit next to it
    int i;
    for (i = length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of digits[i] but greater than digits[i]
    int j;
    for (j = length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the digits after the position i
    int start = i + 1;
    int end = length - 1;
    while (start < end) {
        temp = digits[start];
        digits[start] = digits[end];
        digits[end] = temp;
        start++;
        end--;
    }

    // Convert the array of digits back to an integer
    return Integer.parseInt(new String(digits));
}

