public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Maximum squares required is i (1^2 + 1^2 + ...)
    }
    for (int i = 2; i * i <= n; i++) {
        for (int j = i * i; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - i * i] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
        if (n <= 3) {
            return n;
        }
        int res = n;
        for (int i = 1; i <= n; i++) {
            int temp = i * i;
            if (temp > n) {
                break;
            } else {
                res = Math.min(res, 1 + minPerfectSquareSum(n - temp));
            }
        }
        return res;
    }

